 return np.eye(3)*np.cos(x)+(1-np.cos(x))*np.outer(a,a)+np.sin(x)*K
def fk(q):
 T=np.eye(4)
 for pi,ai,qi in zip(p,axes,q):
  rr=rot(ai,qi); E=np.eye(4);E[:3,:3]=rr;E[:3,3]=pi-rr@pi;T=T@E
 B=np.eye(4);c,s=np.cos(bp[2]),np.sin(bp[2]);B[:3,:3]=[[c,-s,0],[s,c,0],[0,0,1]];B[:3,3]=[bp[0],bp[1],0]
